SELECT
id AS slotId,
start_at AS startAt,
end_at AS endAt,
status
FROM place_availability
WHERE place_id = #{placeId}
AND start_at >= #{fromAt}
AND start_at < #{toAt}
ORDER BY start_at ASC

mapper.update:
UPDATE place_availability
SET status = #{status}
WHERE id = #{slotId}
AND place_id = #{placeId}
AND status <> 'RESERVED'
